namespace ghidra.app.plugin.core.analysis;

using ghidra.app.services;
using ghidra.app.services;
using ghidra.app.util.importer;
using ghidra.program.model.address;
using ghidra.program.model.address;
using ghidra.program.model.listing;
using ghidra.program.model.mem;
using ghidra.util;
using ghidra.util.exception;
using ghidra.util.exception;
using ghidra.util.task;

public class SegmentedCallingConventionAnalyzer : AbstractAnalyzer {
	private static string NAME = "Segmented X86 Calling Conventions";
	private static readonly string DESCRIPTION =
		"Analyzes X86 programs with segmented address spaces to identify a calling convention for each function.  This analyzer looks at the type of return used for the function to identify the calling convention.";

	public SegmentedCallingConventionAnalyzer() : base(NAME, DESCRIPTION, AnalyzerType.FUNCTION_ANALYZER)
    {
		setDefaultEnablement(true);
		setSupportsOneTimeAnalysis();
	}

	/* @Override */
	public bool canAnalyze(Program program) {
		return program.getMinAddress() is SegmentedAddress &&
			program.getLanguage().supportsPcode();
	}

	void checkReturn(Program program, Instruction instr) {
		string mnemonic = instr.getMnemonicString().toLowerCase();
		if (mnemonic.startsWith("ret")) {
			string convention = null;
			//Scalar purge = instr.getScalar(0);
			int b = 0;
			try {
				b = program.getMemory().getByte(instr.getMinAddress()) & 0xff;
			}
			catch (MemoryAccessException e) {
				return;
			}
			switch (b) {
				case 0xca:
					convention = "__stdcall16far";
					break;
				case 0xcb:
					convention = "__cdecl16far";
					break;
				case 0xc3:
					convention = "__cdecl16near";
					break;
				case 0xc2:
					convention = "__stdcall16near";
					break;
			}
			if (convention != null) {
				Function func =
					program.getFunctionManager().getFunctionContaining(instr.getMinAddress());
				if (func != null) {
					try {
						func.setCallingConvention(convention);
					}
					catch (InvalidInputException e) {
						Msg.error(this, "Unexpected Exception: " + e.getMessage(), e);
					}
				}
			}
			return;
		}
	}

	/* @Override */
	public bool added(Program program, AddressSetView set, TaskMonitor monitor, MessageLog log)
    {
		InstructionIterator instructions = program.getListing().getInstructions(set, true);
		while (instructions.hasNext()) {
			Instruction next = instructions.next();
			checkReturn(program, next);
		}
		return true;
	}

}
